export const __metadata = { PACKAGE_NAME: '@wix/user-management' };

export function getAccount(httpClient: HttpClient): GetAccountSignature {
  return (accountId: string) =>
    universalGetAccount(
      accountId,
      // @ts-ignore
      { httpClient }
    );
}

interface GetAccountSignature {
  /**
   * Retrieves an account.
   * @param - Account ID to retrieve.
   */
  (accountId: string): Promise<
    NonNullablePaths<
      AccountResponse,
      | `account.accountId`
      | `account.slug`
      | `account.status`
      | `account.accountOwner`
      | `account.accountProperties.isTeam`
      | `account.accountProperties.coBranding`
      | `account.accountProperties.dataLocality`,
      4
    >
  >;
}

export function createAccount(httpClient: HttpClient): CreateAccountSignature {
  return (user: User, options?: CreateAccountOptions) =>
    universalCreateAccount(
      user,
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface CreateAccountSignature {
  /**
   * Creates a new Wix account, and creates a new Wix user as the account owner.
   * The newly created account is a child account of the account used to create it, making that account its parent.
   *
   * > **Important**: This call requires an account level API key.
   * @param - The user to create under the new account, with the roles defined in `roles`.
   * @param - Filter options.
   */
  (user: User, options?: CreateAccountOptions): Promise<
    NonNullablePaths<
      CreateAccountResponse,
      `account.accountId` | `user.userId`,
      3
    >
  >;
}

