export function createAccountAsCollaborator(
  httpClient: HttpClient
): CreateAccountAsCollaboratorSignature {
  return (
    user: User,
    options?: NonNullablePaths<
      CreateAccountAsCollaboratorOptions,
      `collaboratorRoles` | `siteId`,
      2
    >
  ) =>
    universalCreateAccountAsCollaborator(
      user,
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface CreateAccountAsCollaboratorSignature {
  /**
   * Creates a new Wix account with a user as the account owner and immediately assigns the account as a collaborator on a specified site with defined roles.
   *
   * This method combines account creation, user registration, and site collaboration assignment in a single operation. The newly created account becomes a child account of the requesting account, establishing a parent-child relationship that allows for centralized management and inherited configurations like custom branding.
   *
   * > **Important**: This call requires an account level API key.
   * @param - User details for creating the new account. When parent_as_owner is omitted, this user is the account owner.
   * When parent_as_owner is set, the parent account's owner is the account owner and this user is added as a team member.
   * The created account is then assigned as a collaborator on the specified site.
   */
  (
    user: User,
    options?: NonNullablePaths<
      CreateAccountAsCollaboratorOptions,
      `collaboratorRoles` | `siteId`,
      2
    >
  ): Promise<
    NonNullablePaths<
      CreateAccountAsCollaboratorResponse,
      | `account.accountId`
      | `assignedCollaboratorRoles`
      | `assignedCollaboratorRoles.${number}.assignmentId`
      | `assignedCollaboratorRoles.${number}.roleId`,
      4
    >
  >;
}

export const onAccountCreated = /*#__PURE__*/ EventDefinition(
  'wix.identity.account.v2.account_created',
  true,
  (event: AccountCreatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ])
    )
)<AccountCreatedEnvelope>();

