const PACKAGE_NAME = '@wix/auto_sdk_user-management_accounts';

/** Retrieves an account. */
export function getAccount(payload: object): RequestOptionsFactory<any> {
  function __getAccount({ host }: any) {
    const metadata = {
      entityFqdn: 'wix.identity.account.v2.account',
      method: 'GET' as any,
      methodFqn: 'com.wixpress.account.api.AccountService.getAccount',
      packageName: PACKAGE_NAME,
      migrationOptions: {
        optInTransformResponse: true,
      },
      url: resolveComWixpressAccountApiAccountServiceUrl({
        protoPath: '/v1/accounts/{accountId}',
        data: payload,
        host,
      }),
      params: toURLSearchParams(payload),
      transformResponse: (payload: any) =>
        transformPaths(payload, [
          {
            transformFn: transformRESTTimestampToSDKTimestamp,
            paths: [
              { path: 'account.dateCreated' },
              { path: 'account.dateUpdated' },
            ],
          },
        ]),
    };

    return metadata;
  }

  return __getAccount;
}

/**
 * Creates a new Wix account, and creates a new Wix user as the account owner.
 * The newly created account is a child account of the account used to create it, making that account its parent.
 *
 * > **Important**: This call requires an account level API key.
 */
export function createAccount(payload: object): RequestOptionsFactory<any> {
  function __createAccount({ host }: any) {
    const metadata = {
      entityFqdn: 'wix.identity.account.v2.account',
      method: 'POST' as any,
      methodFqn: 'com.wixpress.account.api.AccountService.createAccount',
      packageName: PACKAGE_NAME,
      migrationOptions: {
        optInTransformResponse: true,
      },
      url: resolveComWixpressAccountApiAccountServiceUrl({
        protoPath: '/v1/accounts/create',
        data: payload,
        host,
      }),
      data: payload,
    };

    return metadata;
  }

  return __createAccount;
}

